<?php /** Make or change a supplier (screens `supplier-add`, `supplier-edit`). Data: cur, sites, here, errors? */
$id = $cur['supplier_id'] ?? null;
$screen = $cur === null ? 'supplier-add' : 'supplier-edit';
$back = $cur === null ? ['/suppliers/', 'Suppliers'] : ['/suppliers/' . (int) $id, $cur['name']];
$errors = $errors ?? [];
$err = static fn (string $k): string => isset($errors[$k]) ? '<div class="invalid-feedback d-block" id="supplier-form-error-' . e($k) . '">' . e($errors[$k]) . '</div>' : '';
$v = static fn (string $k, mixed $d = ''): string => e((string) ($_POST[$k] ?? $cur[$k] ?? $d));
$text = static fn (string $k, string $label, int $max = 120, string $type = 'text', string $col = 'col-12 col-md-6', string $ph = '') => '<div class="' . $col . '"><label class="form-label fs-12 text-muted" for="supplier-form-field-' . $k . '">' . e($label) . '</label><input type="' . $type . '" name="' . $k . '" id="supplier-form-field-' . $k . '" class="form-control btn-touch' . (isset($errors[$k]) ? ' is-invalid' : '') . '" maxlength="' . $max . '" value="' . $v($k) . '" placeholder="' . e($ph) . '">' . $err($k) . '</div>';
?>
<?= view('shared/header.php', ['id' => $screen, 'title' => $cur === null ? 'New supplier' : 'Change ' . $cur['name'], 'crumbs' => [['Home', '/'], ['Suppliers', '/suppliers/'], [$cur === null ? 'New' : $cur['name'], $cur === null ? null : '/suppliers/' . (int) $id]], 'back' => back_link() ?? $back]) ?>
