            <div class="col-12 col-md-4" id="supplier-form-commissary-row"><label class="form-label fs-12 text-muted" for="supplier-form-field-commissary_site">The site a commissary is</label><select name="commissary_site" id="supplier-form-field-commissary_site" class="form-select btn-touch<?= isset($errors['commissary_site']) ? ' is-invalid' : '' ?>"><option value="">—</option><?php foreach ($sites as $st): ?><option value="<?= (int) $st['scope_id'] ?>" <?= (string) ($_POST['commissary_site'] ?? $cur['commissary_scope_id'] ?? '') === (string) $st['scope_id'] ? 'selected' : '' ?>><?= e($st['name']) ?></option><?php endforeach; ?></select><?= $err('commissary_site') ?></div>
            <?= $text('contact_name', 'Contact', 120, 'text', 'col-12 col-md-4') ?><?= $text('email', 'Email', 200, 'email', 'col-12 col-md-4') ?><?= $text('phone', 'Phone', 60, 'text', 'col-12 col-md-4') ?>
            <div class="col-12"><label class="form-label fs-12 text-muted" for="supplier-form-field-address">Address</label><textarea name="address" id="supplier-form-field-address" class="form-control" rows="2" maxlength="500"><?= $v('address') ?></textarea></div>
